$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent;$failed=@();function Test-RcGate { param([string]$Name,[scriptblock]$Action) try{& $Action;Write-Host "[PASS] $Name"}catch{$script:failed+=$Name;Write-Host "[FAIL] ${Name}: $($_.Exception.Message)" -ForegroundColor Red}}
Test-RcGate 'PowerShell parse' { $errs=@();Get-ChildItem $root -Recurse -Filter *.ps1|? FullName -notmatch '\\.git\\'|%{$t=$null;$e=$null;[void][System.Management.Automation.Language.Parser]::ParseFile($_.FullName,[ref]$t,[ref]$e);$errs+=$e};if($errs){throw ($errs.Message -join '; ')}}
Test-RcGate 'Pester' { & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'tests\run-tests.ps1');if($LASTEXITCODE -ne 0){throw 'Pester invocation failed'}}
Test-RcGate 'Branding bootstrap contract' { $defaults=Get-Content (Join-Path $root 'config\defaults.json') -Raw|ConvertFrom-Json;if($defaults.appName -ne 'DLD Luan Dev' -or $defaults.appVersion -ne '0.9.0-rc.2'){throw 'Brand/version mismatch'};$bootstrap=Get-Content (Join-Path $root 'bootstrap.ps1') -Raw;foreach($value in @('https://github.com/maitrungluan-05/autosetupenvironment','0.9.0-rc.2','DLD-Luan-Dev-v$Version.zip')){if($bootstrap -notmatch [regex]::Escape($value)){throw "Bootstrap missing $value"}}}
Test-RcGate 'Doctor JSON stdout' { $capture=Join-Path $env:TEMP ('dlddev-doctor-'+([guid]::NewGuid().ToString())+'.json');& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'devsetup.ps1') doctor -Json > $capture;if($LASTEXITCODE -notin @(0,1,2)){throw 'Unexpected doctor exit code'};$raw=Get-Content $capture -Raw;$null=$raw|ConvertFrom-Json;Remove-Item $capture -Force }
Test-RcGate 'Version output' { $out=& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'devsetup.ps1') version;if(($out -join "`n") -notmatch 'DLD Luan Dev v0\.9\.0-rc\.2'){throw 'CLI version mismatch'}}
Test-RcGate 'Source safety' { $runtime=Get-ChildItem (Join-Path $root 'src'),(Join-Path $root 'bootstrap.ps1') -Recurse -File -ErrorAction SilentlyContinue|? Extension -eq '.ps1';$bad=$runtime|Select-String -Pattern 'Invoke-Expression|\biex\b|ExecutionPolicy\s+Bypass' -CaseSensitive:$false;if($bad){throw ($bad|% Line|Out-String)}}
Test-RcGate 'Build artifact' { & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'scripts\build-release.ps1');if($LASTEXITCODE -ne 0){throw 'Build failed'}}
Test-RcGate 'Checksum' { & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'scripts\verify-release.ps1');if($LASTEXITCODE -ne 0){throw 'Checksum failed'}}
Test-RcGate 'Archive allow-list' { $zip=Join-Path $root 'dist\DLD-Luan-Dev-v0.9.0-rc.2.zip';Add-Type -AssemblyName System.IO.Compression.FileSystem;$a=[IO.Compression.ZipFile]::OpenRead($zip);try{$names=@($a.Entries|% { $_.FullName -replace '\\','/' });foreach($required in @('devsetup.ps1','dlddev.cmd','devsetup.cmd','src/main.ps1','config/defaults.json','config/environments.json')){if($names -notcontains $required){throw "Missing $required"}};if($names|?{$_ -match '^(tests|dist|\.git)/|\.log$|doctor-output\.json'}){throw 'Disallowed archive content'}}finally{$a.Dispose()}}
if($failed.Count){Write-Host 'RC verification FAILED' -ForegroundColor Red;exit 1};Write-Host 'RC verification PASS' -ForegroundColor Green;exit 0
